package br.com.gestao.stock; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="stock_movements") public class StockMovement{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long productId; @Column(nullable=false) private String productName; @Enumerated(EnumType.STRING) @Column(nullable=false) private MovementType type; @Column(nullable=false) private Integer quantity; private Integer previousStock; private Integer newStock; @Column(length=300) private String note; private String createdBy; @Column(nullable=false) private LocalDateTime createdAt;
 public StockMovement(){} public StockMovement(Long id,Long productId,String productName,MovementType type,Integer quantity,Integer previousStock,Integer newStock,String note,String createdBy,LocalDateTime createdAt){this.id=id;this.productId=productId;this.productName=productName;this.type=type;this.quantity=quantity;this.previousStock=previousStock;this.newStock=newStock;this.note=note;this.createdBy=createdBy;this.createdAt=createdAt;}
 public Long getId(){return id;} public Long getProductId(){return productId;} public String getProductName(){return productName;} public MovementType getType(){return type;} public Integer getQuantity(){return quantity;} public Integer getPreviousStock(){return previousStock;} public Integer getNewStock(){return newStock;} public String getNote(){return note;} public String getCreatedBy(){return createdBy;} public LocalDateTime getCreatedAt(){return createdAt;}
}
